def cycles(graph):
    nodes=set(graph)|{v for vs in graph.values() for v in vs}
    def reach(n):
        seen={n}; todo=[n]
        while todo:
            for v in graph.get(todo.pop(),[]):
                if v not in seen: seen.add(v); todo.append(v)
        return seen
    r={n:reach(n) for n in nodes}; remaining=set(nodes); out=[]
    while remaining:
        n=min(remaining); group=sorted(v for v in remaining if v in r[n] and n in r[v]); remaining.difference_update(group)
        if len(group)>1 or n in graph.get(n,[]): out.append(group)
    return sorted(out)

